INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28801, 'Titus 3:11', 'Titus', 3, 11, '&nbsp;ځکه چې تا ته پته ده چې داسې کس ګمراه شوے دے او ګناه ګار دے او خپل ځان يې مجرم کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28802, 'Titus 3:12', 'Titus', 3, 12, '&nbsp;ما دا اراده وکړه چې تاسو ته ارتِماس يا تخيکوس درولېږم. نو چې په دوئ دواړو کښې هر يو درورسيږى نو چې ما سره مِلاو شئ ځکه چې ما په نيکوپوليس کښې د ژمې تېرولو فېصله کړې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28803, 'Titus 3:13', 'Titus', 3, 13, '&nbsp;نو زيناس وکيل او د اپولوس په راتلو کښې د هغوئ هر رنګه مدد وکړئ، او خيال کوئ چې هغوئ ته د څۀ څيز کمے رانۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28804, 'Titus 3:14', 'Titus', 3, 14, '&nbsp;زمونږ خلق دې خپل ځانونه نېکو کارونو ته وقف کړى، د دې دپاره چې د ضرورتمندو خلقو حاجتونه سمدستى پوره شى نو چې ژوند بې‌فائدې نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28805, 'Titus 3:15', 'Titus', 3, 15, '&nbsp;هغه ټول ملګرى چې ما سره دى تاسو ته سلام وائى. هغوئ ته هم زمونږ سلام وايه چې په ايمان کښې مونږ سره مينه کوى. په تاسو ټولو دې د خُدائ پاک فضل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28806, 'Philemon 1:1', 'Philemon', 1, 1, '&nbsp;زۀ پولوس دا خط چې د عيسىٰ مسيح دپاره قېدى يم او زمونږ د ورور تيموتيوس د طرف نه خپل ګران د خدمت ملګرى فيليمون', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28807, 'Philemon 1:2', 'Philemon', 1, 2, '&nbsp;او ورسره خپلې خور افيه او ورور ارخيپوس ته چې زمونږ پرجوش کارکن دے او ستاسو د کور جماعت ته ليکم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28808, 'Philemon 1:3', 'Philemon', 1, 3, '&nbsp;زمونږ د خُدائ پلار او د مالِک عيسىٰ مسيح د طرف نه دې په تاسو فضل او سلامتى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28809, 'Philemon 1:4', 'Philemon', 1, 4, '&nbsp;زۀ چې کله تاسو په خپلو دُعاګانو کښې يادوم نو د خپل خُدائ پاک شُکر کوم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28810, 'Philemon 1:5', 'Philemon', 1, 5, '&nbsp;ځکه چې زۀ ستاسو د ټولو مقدسينو سره د مينې او په مالِک عيسىٰ مسيح د ايمان نه خبر يم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28811, 'Philemon 1:6', 'Philemon', 1, 6, '&nbsp;ستا دپاره زما دا دُعا ده چې کوم شراکت چې د ايمان په وسيله په تا کښې پېدا شوے دے هغه دې نور هم اثرناک شى او تۀ دې د ټولو هغه برکتونو چې په مسيح کښې دى په پوره توګه محسوس کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28812, 'Philemon 1:7', 'Philemon', 1, 7, '&nbsp;اے زما وروره، ما ته ستا په مينه ډېره خوشحالى او تسلى مِلاو شوې ده ځکه چې ستا په سبب د مقدسينو زړونه تازه شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28813, 'Philemon 1:8', 'Philemon', 1, 8, '&nbsp;اګر کۀ زۀ په مسيح کښې دومره زړَور يم چې تا ته د خپل کار کولو حُکم درکړم،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28814, 'Philemon 1:9', 'Philemon', 1, 9, '&nbsp;خو زۀ تا ته د مينې په بنياد مِنت کوم او زۀ پولوس دا د يو بوډا سړى په طور او هم د عيسىٰ مسيح د يو قېدى په حيثيت کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28815, 'Philemon 1:10', 'Philemon', 1, 10, '&nbsp;زۀ تا ته د خپل زوئ اونيسيموس دپاره مِنت کوم، د چا چې زۀ د قېد په دوران کښې روحانى پلار جوړ شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28816, 'Philemon 1:11', 'Philemon', 1, 11, '&nbsp;اول خو هغه ستا دپاره بې‌کاره وو، خو اوس هغه ستا او زما دواړو د کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28817, 'Philemon 1:12', 'Philemon', 1, 12, '&nbsp;زۀ هغه تا ته واپس درلېږم هغه څوک چې زما د زړۀ سر دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28818, 'Philemon 1:13', 'Philemon', 1, 13, '&nbsp;ما غوښتل چې هغه ځان سره پاتې کړم، چې د زيرى دپاره د قېد کېدلو په دوران کښې ستا په ځائ هغه زما خِدمت وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28819, 'Philemon 1:14', 'Philemon', 1, 14, '&nbsp;خو ما ستا د مرضۍ نه بغېر داسې يو کار کول ونۀ غوښتل، ځکه چې ستا نېک کار ستا په مرضۍ دے او د زبردستۍ په وجه نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28820, 'Philemon 1:15', 'Philemon', 1, 15, '&nbsp;شايد چې هم دا وجه وه چې هغه ستا نه د لږ وخت دپاره جدا شو، د دې دپاره چې هغه به بيا د تل دپاره تا سره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28821, 'Philemon 1:16', 'Philemon', 1, 16, '&nbsp;خو نور هغه د غلام په شان نه بلکې د غلام نه زيات دے، ځکه چې هغه ما ته يو ګران ورور دے. نو اوس به هغه تا ته د يو انسان او په مالِک کښې د ورور په شان وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28822, 'Philemon 1:17', 'Philemon', 1, 17, '&nbsp;نو کۀ تۀ ما خپل شريک ګڼې نو دے داسې قبول کړه لکه څنګه چې تۀ ما قبلوې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28823, 'Philemon 1:18', 'Philemon', 1, 18, '&nbsp;او کۀ هغۀ چرې تا ته څۀ نقصان درکړے وى او يا پرې ستا څۀ قرض وى نو هغه ما پسې وليکه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28824, 'Philemon 1:19', 'Philemon', 1, 19, '&nbsp;زۀ پولوس درته په خپل لاس دا ليکم چې زۀ به يې په خپله درته واپس کړم، او دې وئيلو ته ضرورت نشته چې زما په تا کوم قرض دے نو هغه هم تۀ په خپله يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28825, 'Philemon 1:20', 'Philemon', 1, 20, '&nbsp;اے وروره، زۀ په مالِک کښې تاسو نه د خير طمع کوم. هغه دا چې په مسيح کښې زما زړۀ تازه کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28826, 'Philemon 1:21', 'Philemon', 1, 21, '&nbsp;زما ستا په فرمانبردارۍ باور دے، زۀ درته دا ليکم او په دې پوهېږم چې تۀ به زما دا خواست پوره کړې، بلکې زما د وينا نه به زيات څۀ وکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28827, 'Philemon 1:22', 'Philemon', 1, 22, '&nbsp;او بله دا چې زما دپاره يوه کوټه تياره کړه، ځکه چې زما اُميد دے چې ستاسو د دُعاګانو په وسيله به زۀ بيا تاسو له درشم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28828, 'Philemon 1:23', 'Philemon', 1, 23, '&nbsp;اِپفراس چې د عيسىٰ مسيح په وجه ما سره قېدى دے تا ته سلامونه وائى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28829, 'Philemon 1:24', 'Philemon', 1, 24, '&nbsp;او هم دغه شان مرقوس، اريسترخوس، ديماس او لوقا هم چې په دې خدمت کښې زما ملګرى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28830, 'Philemon 1:25', 'Philemon', 1, 25, '&nbsp;د مالِک عيسىٰ مسيح فضل دې تاسو ټولو سره مل وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28831, 'Hebrews 1:1', 'Hebrews', 1, 1, '&nbsp;په تېره زمانه کښې خُدائ پاک زمونږ پلار نيکۀ ته ډېر ځله په مختلفو طريقو د نبيانو په وسيله خبرې وکړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28832, 'Hebrews 1:2', 'Hebrews', 1, 2, '&nbsp;خو په دې آخره زمانه کښې هغۀ مونږ ته د خپل زوئ په وسيله خبرې وکړې چا چې هغه د ټولو څيزونو وارث مقرر کړو او د هغۀ په وسيله يې کائنات پېدا کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28833, 'Hebrews 1:3', 'Hebrews', 1, 3, '&nbsp;هغه د خُدائ د جلال مظهر او هغه د خُدائ د ذات تصوير دے او هغه ټول کائنات په خپل زورَور کلام سمبالوى. کله چې هغۀ زمونږ ګناهونه پاک کړل نو په آسمان کښې د قادر مطلق خُدائ ښى لاس ته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28834, 'Hebrews 1:4', 'Hebrews', 1, 4, '&nbsp;نو څنګه چې زوئ د فرښتو نه لوئ دے نو دغه شان د هغۀ نوم د هغوئ نه لوئ دے کوم چې هغۀ ته په ميراث کښې مِلاو شوے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28835, 'Hebrews 1:5', 'Hebrews', 1, 5, '&nbsp;ځکه چې خُدائ پاک کله هم کومې فرښتې ته دا نۀ دى فرمائيلى چې، ”تۀ زما زوئ يې، او د نن نه زۀ ستا پلار شوم.“ او بيا دا چې، ”زۀ به د هغۀ پلار يم او هغه به زما زوئ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28836, 'Hebrews 1:6', 'Hebrews', 1, 6, '&nbsp;او بيا چې خُدائ پاک خپل اول پېدا شوے، دُنيا ته راولى نو هغه فرمائى چې، ”د خُدائ پاک ټولې فرښتې دې هغۀ ته سجده وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28837, 'Hebrews 1:7', 'Hebrews', 1, 7, '&nbsp;او د فرښتو په حقله فرمائى چې، ”هغه د خپلو فرښتو نه هواګانې جوړوى او د خپلو خادِمانو نه د اور شُغلې جوړوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28838, 'Hebrews 1:8', 'Hebrews', 1, 8, '&nbsp;خو خپل زوئ ته فرمائى چې، ”اے خُدايه پاکه، ستا تخت به تل تر تله وى او د صداقت امسا ستا د بادشاهۍ امسا ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28839, 'Hebrews 1:9', 'Hebrews', 1, 9, '&nbsp;تا د صداقت سره مينه او د شرارت نه نفرت وکړو، په دې وجه خُدائ پاک، يعنې ستاسو خُدائ پاک، تۀ د خوشحالۍ په تېلو د خپلو ملګرو په نسبت زيات مسح کړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28840, 'Hebrews 1:10', 'Hebrews', 1, 10, '&nbsp;او، ”اے مالِکه، تا د زمکې بنياد د ازل نه کېښودو او آسمان ستا د لاس کار دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28841, 'Hebrews 1:11', 'Hebrews', 1, 11, '&nbsp;هغه به فنا شى خو تۀ به باقى پاتې يې، او هغه ټول به د جامو په شان زاړۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28842, 'Hebrews 1:12', 'Hebrews', 1, 12, '&nbsp;تۀ به هغوئ د زړې چُوغې په شان راونغاړې او د جامو په شان به هغوئ بدل کړے شى. خو تۀ به تل تر تله هم هغه يې او د تل دپاره به قائم دائم يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28843, 'Hebrews 1:13', 'Hebrews', 1, 13, '&nbsp;خو خُدائ پاک فرښتې ته کله هم نۀ دى فرمائيلى چې، ”تۀ زما ښى لاس ته کښېنه ترڅو چې زۀ ستا دشمنان ستا د پښو د لاندې چوکۍ جوړ نۀ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28844, 'Hebrews 1:14', 'Hebrews', 1, 14, '&nbsp;ولې ټولې فرښتې خِدمت ګزار روحونه نۀ دى کوم چې د هغه خلقو د خِدمت دپاره رالېږلے شوى دى څوک چې د خلاصون وارثان دى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28845, 'Hebrews 2:1', 'Hebrews', 2, 1, '&nbsp;په دې وجه مونږ له په کار دى چې په هغه څۀ ډېر غور وکړُو څۀ چې مونږ واورېدل، نو هسې نه چې مونږ د دې نه لرې لاړ شُو او ونۀ ښوئيږو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28846, 'Hebrews 2:2', 'Hebrews', 2, 2, '&nbsp;ځکه کوم کلام چې د فرښتو په وسيله ورکړے شوے وو هغه قائم پاتې شو او هرې خطا او نافرمانۍ ته ټيک سزا مِلاو شوه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28847, 'Hebrews 2:3', 'Hebrews', 2, 3, '&nbsp;نو مونږ څنګه د سزا نه بچ کېدے شُو کۀ مونږ د دې لوئ خلاصون نه بې‌پرواه شُو، د کوم چې اول مالِک اعلان وکړو او بيا هغه خلقو وکړو چا چې هغه واورېدلو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28848, 'Hebrews 2:4', 'Hebrews', 2, 4, '&nbsp;خُدائ پاک هم د خپلو نښو، عجيبه کارونو او قِسما قِسم معجزو په کولو او د خپلې مرضۍ په مطابق د روحُ القُدس د نعمتونو په ويشلو د هغې تصديق وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28849, 'Hebrews 2:5', 'Hebrews', 2, 5, '&nbsp;نو خُدائ پاک هغه راتلونکې دُنيا چې مونږ يې بيان کوُو د فرښتو تابع نۀ کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28850, 'Hebrews 2:6', 'Hebrews', 2, 6, '&nbsp;بلکې په صحيفو کښې يو ځائ وئيل شوى دى چې، ”انسان څۀ وى چې تۀ پرې نظر ساتې، نو بنيادم څۀ وى چې تۀ يې خيال ساتې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28851, 'Hebrews 2:7', 'Hebrews', 2, 7, '&nbsp;تا هغه د فرښتو نه لږ کم کړے دے او ورته دې د جلال او عزت تاج ورپه سر کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28852, 'Hebrews 2:8', 'Hebrews', 2, 8, '&nbsp;او تا په هر څيز پوره اختيار ورکړے دے او هر څۀ دې د هغۀ د پښو لاندې کړى دى.“ نو چې خُدائ پاک ټول څيزونه د هغوئ تابع کړل نو هغۀ هيڅ څيز داسې پرې نۀ ښودلو چې هغه يې د هغۀ تابع کړے نۀ وى، خو مونږ تر اوسه ټول څيزونه د هغۀ تابع نۀ وينو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28853, 'Hebrews 2:9', 'Hebrews', 2, 9, '&nbsp;خو مونږ عيسىٰ ګورو، څوک چې د لږ وخت دپاره د فرښتو نه کم کړے شو، خو اوس د مرګ د تکليف تېرولو په وسيله هغۀ ته د جلال او عزت تاج په سر شو، او داسې د خُدائ پاک په فضل هغۀ د ټولو دپاره مرګ وزغملو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28854, 'Hebrews 2:10', 'Hebrews', 2, 10, '&nbsp;نو خُدائ پاک دا ټول څيزونه د خپل ځان دپاره پېدا کړى دى او د هغۀ په وسيله پېدا شوى دى، نو هغۀ دا مناسب وګڼل چې ډېر زامن په جلال کښې داخل کړى، نو چې د تکليفونو په وسيله د خلاصون بانى کامِل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28855, 'Hebrews 2:11', 'Hebrews', 2, 11, '&nbsp;ځکه هغه څوک چې پاکوونکے دے او هغوئ څوک چې پاکيږى د ټولو پلار يو دے، نو په هم دې وجه عيسىٰ هغوئ ته په ورور او خور وئيلو نۀ شرميږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28856, 'Hebrews 2:12', 'Hebrews', 2, 12, '&nbsp;نو هغه فرمائى چې، ”زۀ به خپلو خلقو ته ستا د نوم لوئى بيان کړم، ستا ثناء صِفت به زۀ د جماعت په مينځ کښې وکړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28857, 'Hebrews 2:13', 'Hebrews', 2, 13, '&nbsp;او بيا دا چې، ”زۀ به په هغۀ باور وکړم.“ او، ”ګوره، زۀ د هغه بچو سره دلته موجود يم چې خُدائ پاک ما ته راکړى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28858, 'Hebrews 2:14', 'Hebrews', 2, 14, '&nbsp;بيا لکه چې د هغۀ بچى انسانان دى، دغه شان عيسىٰ هم انسان شو د دې دپاره چې د مرګ په وسيله هغه څوک چې په مرګ يې قُدرت حاصل وو، يعنې اِبليس، تباه کړى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28859, 'Hebrews 2:15', 'Hebrews', 2, 15, '&nbsp;او هغوئ آزاد کړى څوک چې ټول عُمر د مرګ د يرې په غلامۍ کښې ګرفتار وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28860, 'Hebrews 2:16', 'Hebrews', 2, 16, '&nbsp;ځکه چې په حقيقت کښې هغه د فرښتو دپاره نه، بلکې د اِبراهيم د نسل مدد دپاره راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28861, 'Hebrews 2:17', 'Hebrews', 2, 17, '&nbsp;هم دغه وجه ده چې عيسىٰ ته په هر لحاظ د خپلو وروڼو په شان جوړېدل په کار وُو چې هغه د خُدائ پاک په خِدمت کولو کښې داسې لوئ اِمام شى چې زړۀ سواندے او وفادار وى، او د خلقو د ګناهونو دپاره د خپل ځان کفاره ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28862, 'Hebrews 2:18', 'Hebrews', 2, 18, '&nbsp;ځکه چې هغه په خپله په تکليفونو کښې وآزمائيلے شو نو هغه د دې قابل دے چې د هغوئ مدد وکړى څوک چې آزمائيلے کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28863, 'Hebrews 3:1', 'Hebrews', 3, 1, '&nbsp;نو ځکه اے پاکو وروڼو او خوېندو، تاسو چې په آسمانى بلنه کښې شريک يئ، په هغه رسول او مشر اِمام عيسىٰ غور وکړئ د چا چې مونږ اِقرار کوُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28864, 'Hebrews 3:2', 'Hebrews', 3, 2, '&nbsp;هغه د هغه خُدائ پاک وفادار شو چا چې هغه منتخب کړے وو او لکه څنګه چې موسىٰ د خُدائ پاک په ټول کور کښې وفادار وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28865, 'Hebrews 3:3', 'Hebrews', 3, 3, '&nbsp;خو عيسىٰ د موسىٰ نه زيات د جلال لائق دے، لکه څنګه چې د کور جوړونکے د کور نه زيات عزتمند وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28866, 'Hebrews 3:4', 'Hebrews', 3, 4, '&nbsp;ځکه چې د هر يو کور څوک نه څوک جوړونکے وى، خو د ټولو څيزونو جوړونکے خُدائ پاک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28867, 'Hebrews 3:5', 'Hebrews', 3, 5, '&nbsp;موسىٰ د خُدائ پاک په ټول کور کښې د خادِم په شان وفادار وو د دې دپاره چې د راتلونکو خبرو ګواهى ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28868, 'Hebrews 3:6', 'Hebrews', 3, 6, '&nbsp;خو مسيح د زوئ په حيثيت د خُدائ په کور اختيارمند دے، او مونږ د هغۀ کور يُو کۀ چرې مونږ په هغه اعتماد او فخر قائم پاتې شُو چې د اُميد سره تعلق ساتى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28869, 'Hebrews 3:7', 'Hebrews', 3, 7, '&nbsp;په دې وجه څنګه چې روحُ القُدس فرمائى چې، ”کۀ تاسو نن ورځ د هغۀ آواز واورئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28870, 'Hebrews 3:8', 'Hebrews', 3, 8, '&nbsp;نو خپل زړونه مۀ سختوئ څنګه چې مو د بغاوت په وخت کښې کړى وُو او د آزمېښت په ورځ مو په بيابان کښې کړى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28871, 'Hebrews 3:9', 'Hebrews', 3, 9, '&nbsp;چرته چې ستاسو پلار نيکۀ زما جاج او آزمېښت وکړو او تر څلوېښتو کالو پورې هغوئ زما کارونه وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28872, 'Hebrews 3:10', 'Hebrews', 3, 10, '&nbsp;په دې وجه زۀ هغې پيړۍ ته غصه وم او ما وفرمائيل چې همېشه د دوئ زړونه زما نه لرى شوى دى، او دوئ زما لارې ونۀ پېژندلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
