(28874, 'Hebrews 3:12', 'Hebrews', 3, 12, '&nbsp;نو وروڼو او خوېندو، خبردار شئ، په تاسو کښې دې د چا داسې بد او بې‌ايمانه زړۀ نۀ وى چې د ژوندى خُدائ پاک نه واوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28875, 'Hebrews 3:13', 'Hebrews', 3, 13, '&nbsp;بلکې هره ورځ يو بل له خبردارے ورکوئ، ترڅو چې نن ورځ ده نو چې په تاسو کښې څوک د ګناه د فريب په وجه سخت زړۀ نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28876, 'Hebrews 3:14', 'Hebrews', 3, 14, '&nbsp;ځکه چې مونږ هم د مسيح سره شريک يُو خو کۀ مونږ په خپل اولنى باور تر آخره ټينګ او قائم پاتې شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28877, 'Hebrews 3:15', 'Hebrews', 3, 15, '&nbsp;لکه چې صحيفې فرمائى چې، ”کۀ تاسو نن ورځ د هغۀ آواز واورئ، نو خپل زړونه مۀ سختوئ لکه چې تاسو د بغاوت په وخت کښې کړى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28878, 'Hebrews 3:16', 'Hebrews', 3, 16, '&nbsp;نو اوس دا څوک وو چا چې هغه آواز واورېدو او بيا هم سرکشه شول؟ دا هغوئ ټول نۀ وُو چا چې د موسىٰ په مشرۍ کښې مِصر پرېښودو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28879, 'Hebrews 3:17', 'Hebrews', 3, 17, '&nbsp;او خُدائ پاک د چا نه تر څلوېښتو کالو پورې خفه وو؟ ولې دا هغوئ نۀ وُو، چا چې ګناه وکړه او د چا مړى چې په بيابان کښې پراتۀ وُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
