(28881, 'Hebrews 3:19', 'Hebrews', 3, 19, '&nbsp;نو مونږ وليدل چې د بې‌ايمانۍ په وجه هغوئ د داخلېدو قابل نۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28882, 'Hebrews 4:1', 'Hebrews', 4, 1, '&nbsp;نو په دې وجه چې د هغۀ په آرام کښې د داخلېدو وعده لا کولاو ده، نو مونږ په دې يريږو چې تاسو به هغې ته په رسېدو ناکامه شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28883, 'Hebrews 4:2', 'Hebrews', 4, 2, '&nbsp;ځکه چې زيرے مونږ ته هم د هغوئ په شان راورسېدو، خو هغه کلام چې هغوئ واورېدو هغوئ ته يې فائده ورنۀ کړه، ځکه چې هغوئ په ايمان کښې د هغوئ سره په اتفاق نۀ وُو چا چې کلام واورېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28884, 'Hebrews 4:3', 'Hebrews', 4, 3, '&nbsp;او مونږ چا چې ايمان راوړو په هغه آرام کښې داخلېږو لکه څنګه چې خُدائ پاک وفرمائيل چې، ”نو ما په خپله غصه کښې قسم وخوړلو چې، کله به هم هغوئ زما په آرام کښې داخل نۀ شى،“ کۀ څۀ هم چې دا آرام د دُنيا د جوړېدو نه مخکښې تيار شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28885, 'Hebrews 4:4', 'Hebrews', 4, 4, '&nbsp;ځکه چې هغۀ په يوه موقع د اوومې ورځې په حقله داسې وفرمائيل چې، ”او خُدائ پاک په خپلو کارونو پوره کولو سره په اوومه ورځ څۀ ونۀ کړل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28886, 'Hebrews 4:5', 'Hebrews', 4, 5, '&nbsp;نو په هم دې ځائ کښې هغه بيا فرمائى چې، ”کله به هم هغوئ زما په آرام کښې داخل نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28887, 'Hebrews 4:6', 'Hebrews', 4, 6, '&nbsp;چا چې په شروع کښې دا زيرے واورېدو نو هغوئ په هغه آرام کښې داخل نۀ شول ځکه چې هغوئ نافرمانى وکړله، خو بعضې خلق داسې دى چې په دې کښې به داخل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28888, 'Hebrews 4:7', 'Hebrews', 4, 7, '&nbsp;نو بيا خُدائ پاک د دې آرام دپاره يوه خاص ورځ مقرره کړه او د دومره مودې نه پس هغۀ ورته د داؤد په کِتاب کښې ”د نن ورځ“ وفرمائيل، لکه څنګه چې هغۀ مخکښې فرمائيلى وُو، ”کۀ تاسو نن ورځ د هغۀ آواز واورئ، نو بيا خپل زړونه مۀ سختوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28889, 'Hebrews 4:8', 'Hebrews', 4, 8, '&nbsp;ځکه کۀ چرې يشوَع هغوئ په آرام کښې داخل کړى وے نو خُدائ پاک به د هغې نه پس د بلې ورځې په حقله ذکر نۀ وو کړے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28890, 'Hebrews 4:9', 'Hebrews', 4, 9, '&nbsp;نو بيا د خُدائ پاک د خلقو دپاره د سبت ورځ د آرام ورځ تر اوسه انتظار کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28891, 'Hebrews 4:10', 'Hebrews', 4, 10, '&nbsp;ځکه هغه څوک چې د خُدائ پاک په آرام کښې داخل شى، نو هغوئ به هم د خُدائ پاک په شان د خپلو کارونو نه په آرام شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28892, 'Hebrews 4:11', 'Hebrews', 4, 11, '&nbsp;نو راځئ چې مونږ په هغه آرام کښې د داخلېدو دپاره هر کوشش وکړُو نو چې په مونږ کښې څوک هم د هغوئ په شان د نافرمانۍ په وجه ناکامه نۀ شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
