(28894, 'Hebrews 4:13', 'Hebrews', 4, 13, '&nbsp;او د خُدائ پاک نه يو مخلوق هم پټ نۀ دے بلکې د هغۀ د سترګو د وړاندې ټول بربنډ او بې‌پړدې پراتۀ دى چا ته به چې مونږ حساب ورکوو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28895, 'Hebrews 4:14', 'Hebrews', 4, 14, '&nbsp;زمونږ داسې لوئ مشر اِمام شته چې د آسمانونو نه تېر شو يعنې عيسىٰ چې د خُدائ پاک زوئ دے، نو راځئ چې مونږ د خپل ايمان په اِقرار ټينګ پاتې شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28896, 'Hebrews 4:15', 'Hebrews', 4, 15, '&nbsp;ځکه چې زمونږ داسې مشر اِمام نۀ دے څوک چې زمونږ په کمزورتياو کښې مونږ سره همدردى ونۀ کړى بلکې هغه په ټولو خبرو کښې زمونږ په شان وآزمائيلے شو خو بيا هم بې‌ګناه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28897, 'Hebrews 4:16', 'Hebrews', 4, 16, '&nbsp;نو راځئ چې مونږ د خُدائ پاک د فضل تخت ته ځان په اعتماد سره ورنزدې کړُو نو چې په مونږ رحم وشى او هغه فضل حاصل کړُو چې د حاجت په وخت زمونږ مدد وکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28898, 'Hebrews 5:1', 'Hebrews', 5, 1, '&nbsp;هر مشر اِمام د انسانانو نه د دې دپاره منتخب کيږى چې خُدائ پاک ته د خلقو نمائندګى وکړى او د انسانانو د ګناهونو دپاره نذرانې او قربانۍ پېش کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28899, 'Hebrews 5:2', 'Hebrews', 5, 2, '&nbsp;او هغه د دې جوګه دے چې د ناپوهه او ګمراهانو سره په نرمۍ سلوک وکړى ځکه چې په هغۀ کښې هم هغه شان کمزورتيا شته دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28900, 'Hebrews 5:3', 'Hebrews', 5, 3, '&nbsp;نو په دې وجه هغه ضرور د خپلو او هم د خلقو د ګناهونو دپاره قربانى پېش کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');